def hook(ctx, nb):
    stage = nb.get('stage')
    msg = ''
    if stage == 'need_schema_probe':
        msg = 'Identifier/schema issue: run DESCRIBE or SHOW COLUMNS for the target table, then use exact column names with backticks for spaces, punctuation, parentheses, or reserved words. Do not repeat the same failing SQL.'
    elif stage == 'fixing_empty_result':
        msg = 'Empty SELECT: inspect sample rows or distinct values for the filtered columns, then relax one predicate at a time. Use LIKE, date/numeric casts, or case-insensitive matching when stored formats differ from the question wording.'
    elif stage == 'text_numeric_handling':
        msg = 'Text numeric handling: for ranking, ordering, sums, or comparisons over text columns, cast cleaned values to DECIMAL/SIGNED. Preserve original text only for final display or exact literal storage.'
    elif stage == 'mutation_needs_execution':
        msg = 'Mutation task: after schema probing, execute the INSERT/UPDATE/DELETE with exact requested literals. Backtick unusual identifiers and keep punctuation, spaces, percent signs, unicode, and newlines exactly as requested.'
    elif stage == 'ready_to_commit_candidate':
        msg = 'Before committing a mutation, verify the affected row/state with SELECT. An empty tool result after data-changing SQL can still mean success; do not substitute NULL for missing text fields unless the task explicitly asks for it.'
    elif stage == 'repeated_query_loop':
        msg = 'Repeated query loop: change strategy by probing schema, sampling values, or simplifying predicates instead of rerunning the same SQL.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

def hook(ctx, nb):
    a = ctx.get('action') or {}
    p = ctx.get('predicates') or {}
    if a.get('tool') != 'commit_final_answer':
        return None
    if p.get('commit_before_sql') or p.get('no_sql_yet'):
        return {'kind': 'block_and_prompt', 'message': 'Run at least one SQL query to inspect or modify the database before committing a final answer.'}
    if p.get('commit_empty_answer') and not (p.get('mutation_task') and (p.get('mutation_not_attempted') or nb.get('stage') == 'mutation_needs_execution')):
        return {'kind': 'block_and_prompt', 'message': 'Do not commit an empty answer for a SELECT-style task; use SQL evidence to provide the requested values.'}
    if p.get('mutation_task') and p.get('mutation_not_attempted') and not (p.get('remaining_rounds_low') and nb.get('stage') == 'mutation_needs_execution'):
        return {'kind': 'block_and_prompt', 'message': 'This is a database mutation task; execute the INSERT/UPDATE/DELETE before committing so the final database state matches the request.'}
    return None
